package org.eclipse.rdf4j.sail.lmdb.evaluation;

/**
 * The fan-out facts of one join order, per depth: the prefix rows that reach the depth, the DISTINCT keys those rows
 * carry into the depth's pattern, the probability that such a key has any rows, and the rows one key fans out to.
 * <p>
 * Strategies that memoise a branch per probe key, count a branch without enumerating it, or pack lanes once per key
 * price themselves from these facts; the enumerated product ({@link #enumeratedRows()}, the same arithmetic as
 * {@link LmdbNativeWork#rowsOut}) stays what the enumerating strategies pay.
 */
